WITH with_windows AS (SELECT *, DENSE_RANK() OVER w_running AS amount_dense_rank, NTILE(3) OVER (PARTITION BY merchant ORDER BY amount DESC, id ASC) AS amount_bucket, FIRST_VALUE(amount, TRUE) OVER (ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_amount, NTILE(10) OVER (PARTITION BY txn_type ORDER BY amount ASC, id ASC) AS amount_bucket_2, AVG(amount) OVER (PARTITION BY account_id ORDER BY CAST(txn_time AS BIGINT) ASC RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS amount_avg_90d FROM transactions WINDOW w_running AS (PARTITION BY merchant, account_id ORDER BY amount DESC NULLS FIRST)) SELECT id, txn_type, amount, amount_dense_rank, amount_bucket, amount_bucket_2, amount_avg_90d, CASE WHEN txn_type RLIKE '^(DEBIT|FEE)$' THEN 'GROUP_B' WHEN txn_type RLIKE '^(CREDIT|REFUND)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS txn_type_zone FROM with_windows;
